    (1, 1304, 'TUBO DE LLAMA COMPLETO PARA QUEMADOR SPARKGAS11', 2, 1, 'ACTIVO', 'A', 0, 1, 'S', null, null, null, 610, 1, 2, 1, null, null, null, null, '0013020008', '0013020008', null, null, 1303, false, null, false, 0, 'NO', null),
